import React, { useState } from 'react';
import axios from 'axios';

export default function VideoDetection() {
  const [videoFile, setVideoFile] = useState(null);
  const [status, setStatus] = useState("Waiting for video...");
  const [videoUrl, setVideoUrl] = useState(null);

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    setVideoFile(file);
    setVideoUrl(null);
    setStatus("Video selected. Ready to process.");
  };

  const handleUpload = async () => {
    if (!videoFile) return alert("Please select a video.");

    setStatus("Uploading and processing video...");

    const formData = new FormData();
    formData.append("file", videoFile);

    try {
      const response = await axios.post("http://127.0.0.1:8000/v/", formData);
      const filename = response.data.video;

      setStatus("Processing complete. Showing video...");
      setVideoUrl(`http://127.0.0.1:8000${filename}`);
    } catch (error) {
      console.error("Error:", error);
      setStatus("Processing failed.");
      alert("Video processing failed.");
    }
  };

  return (
    <div style={{ padding: 30, fontFamily: 'Segoe UI' }}>
      <h2>🎥 YOLOv8 Video Weapon Detection</h2>

      <input type="file" accept="video/*" onChange={handleFileChange} />
      <br /><br />
      <button onClick={handleUpload}>Submit for Detection</button>
      <p><strong>Status:</strong> {status}</p>

      {videoUrl && (
        <div style={{ marginTop: 30 }}>
          <h3>📽 Processed Video</h3>
          <video width="640" height="360" controls>
            <source src={videoUrl} type="video/mp4" />
            Your browser does not support the video tag.
          </video>
        </div>
      )}
    </div>
  );
}
